'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/navbar/md-gb-nav-bar.js';
import '@material/web/labs/gb/components/navbar/md-gb-nav-bar-item.js';
import {NavBarElement} from '@material/web/labs/gb/components/navbar/nav-bar-element.js';
import {NavBarItemElement} from '@material/web/labs/gb/components/navbar/nav-bar-item-element.js';

/**
 * A Material Design gBreeze navigation bar custom element. Wraps <md-gb-nav-bar>.
 * Docs: https://material-web.dev/3.0/components/navigation-bar/
 */
export const MdNavBar = createComponent({
  react: React,
  tagName: 'md-gb-nav-bar',
  elementClass: NavBarElement,
  events: {
    onChange: 'change' as EventName<Event>,
  },
});

export type MdNavBarProps = React.ComponentProps<typeof MdNavBar>;

/**
 * A Material Design gBreeze navigation bar item custom element. Wraps <md-gb-nav-bar-item>.
 * Docs: https://material-web.dev/3.0/components/navigation-bar/
 */
export const MdNavBarItem = createComponent({
  react: React,
  tagName: 'md-gb-nav-bar-item',
  elementClass: NavBarItemElement,
});

export type MdNavBarItemProps = React.ComponentProps<typeof MdNavBarItem>;
